sited.script:

function home_list_parse(url, jsonString){
    try {
        // 步驟 1: 將 JSON 字串解析成 JavaScript 的陣列
        const data = JSON.parse(jsonString);

        // 步驟 2: 檢查解析後的資料是否為一個陣列
        if (!Array.isArray(data)) {
          return null;
        }

        // 步驟 3: 遍歷陣列，將每個子陣列映射 (map) 成一個結構化的物件
        const formattedData = data.map(item => {
          // 有些標題包含 HTML <a> 標籤，我們需要將其清除
          let title = item[1];
          const linkRegex = /<a [^>]+>(.+)<\/a>/;
          const match = title.match(linkRegex);

          if (match && match[1]) {
            // 如果有匹配到 <a> 標籤，則取出其中的文字作為標題
            title = match[1];
          }

          // 回傳結構化的物件
          if (item[0]) {
              return {
                url: "https://anime1.me/?cat=" + item[0],
                name: title
              };
          } else {
              return {
                url: "https://anime1.pw/?cat=" + item[1].match(/cat=(\d+)/),
                name: title
              };
          }
        });

        return JSON.stringify(formattedData);

    } catch (error) {
        return null;
    }
}

// 核心的「內容列表」解析函式
function list_parse(url, jsonString) {
    var key = decodeURIComponent(url.match(/keyword=([^&]+)/)[1]);
    try {
        const data = JSON.parse(jsonString);

        if (!Array.isArray(data)) {
            return null;
        }

        // 使用 flatMap，符合條件的回傳 [物件]，不符合的回傳 []
        const finalData = data.flatMap(item => {
            let title = item[1];
            const linkRegex = /<a [^>]+>(.+)<\/a>/;
            const match = title.match(linkRegex);

            if (match && match[1]) {
                title = match[1];
            }

            if (item[0] && title.match(key)) {
                // 符合條件，回傳一個包含物件的陣列
                return [{
                    url: "https://anime1.me/?cat=" + item[0],
                    name: title
                }];
            } else if (title.match(key)) {
                 // 符合條件，回傳一個包含物件的陣列
                return [{
                    url: "https://anime1.pw/?cat=" + item[1].match(/cat=(\d+)/),
                    name: title
                }];
            } else {
                // 不符合條件，回傳空陣列，該元素將被自動移除
                return [];
            }
        });

        return JSON.stringify(finalData);

    } catch (error) {
        return null;
    }
}

function book_parse_url(url, html) {
    var $ = cheerio.load(html);
    var urls = [];
    urls.push(url);

    // 將選擇結果存到變數中，避免重複查詢
    var prevLink = $('div.nav-previous a');

    // 正確的判斷方式：檢查集合的長度
    if (prevLink.length > 0) {
        // 直接在 Cheerio 物件上取得屬性
        urls.push("CALL::" + prevLink.attr('href'));
    }
    return JSON.stringify(urls);
}

// 影片播放來源的解析函式
function book_parse_api_response(url, html) {
    var $ = cheerio.load(html);
    var sections = [];
    $("h2 a").each(function(){
        sections.push({name: $(this).text().match(/\[[\.\d]+\]/)[0], url: $(this).attr("href")});
    });
    var book = {
        name: gbk2big5.traditionalized($("h1.page-title").text().trim()),
        logo: "https://sta.anicdn.com/playerImg/8.jpg",
        sections: sections
    };
    return JSON.stringify(book);
}

function section_parse(url, html) {
    return JSON.stringify({type:"webview_player", data: url});
}

sited.WebViewInjection:

            javascript:(function() {
    // 定義一個變數來儲存定時器的 ID (儘管在這個無限模式下我們不會用到它，但這是良好的實踐)
    let intervalId = null;

    // 1. 定義您的核心邏輯
    function runInjection() {
        try {
            // 這裡直接運行清理後的腳本
            var player = document.querySelector('.vjscontainer');

            if (player) {
                // ⭐ 核心邏輯：成功找到並處理元素
                document.body.style.visibility = 'hidden';

                var current = player;
                while (current && current.tagName !== 'BODY') {
                    current.style.visibility = 'visible';
                    var siblings = Array.from(current.parentNode.children);
                    siblings.forEach(function(sibling) {
                        if (sibling !== current) {
                            sibling.style.display = 'none';
                        }
                    });
                    current = current.parentElement;
                }

                document.body.style.visibility = 'visible';
                document.body.style.margin = '0';
                document.body.style.padding = '0';
            } else {
                var player = document.querySelector('.player-space');
                if (player) {
                    // ⭐ 核心邏輯：成功找到並處理元素
                    document.body.style.visibility = 'hidden';

                    var current = player;
                    while (current && current.tagName !== 'BODY') {
                        current.style.visibility = 'visible';
                        var siblings = Array.from(current.parentNode.children);
                        siblings.forEach(function(sibling) {
                            if (sibling !== current) {
                                sibling.style.display = 'none';
                            }
                        });
                        current = current.parentElement;
                    }

                    document.body.style.visibility = 'visible';
                    document.body.style.margin = '0';
                    document.body.style.padding = '0';
                }
            }

            // ⭐ 關鍵修改：始終返回 true/false 已經不重要，因為外層不會停止它
            return false; // 返回 false 只是習慣，不影響這裡的無限循環

        } catch (e) {
            // 如果腳本執行失敗，捕獲錯誤但繼續輪詢
            return false;
        }
    }

    // 2. 啟動定時器，每 1000 毫秒（1 秒）執行一次，且永不停止
    intervalId = setInterval(runInjection, 1000);

    // 備註：在這種模式下，我們必須依賴 WebView 的銷毀來停止定時器。

})();
